import inspect

import pytest

from metrics.calc import percentile


def test_fix_percentile_function_in_metrics_calc():
    assert percentile([1, 2, 3, 4], 50) == pytest.approx(2.5)


def test_use_linear_interpolation_between_the_two_neighbouring_order_statistics():
    assert percentile([10, 20], 37.5) == pytest.approx(13.75)


def test_compute_rank_as_p_over_100_times_n_minus_1():
    assert percentile([0, 10, 20, 30, 40], 40) == pytest.approx(16.0)


def test_interpolate_between_floor_and_ceil_ranks():
    assert percentile([0, 10, 20], 75) == pytest.approx(15.0)


def test_return_linearly_interpolated_percentile_using_standard_linear_method():
    data = [1, 2, 3, 4]
    expected = {
        0: 1.0,
        25: 1.75,
        50: 2.5,
        75: 3.25,
        100: 4.0,
    }
    for p, value in expected.items():
        assert percentile(data, p) == pytest.approx(value)


def test_do_not_use_naive_nearest_rank_index():
    assert percentile([0, 100, 200, 300, 400], 40) == pytest.approx(160.0)


def test_do_not_change_function_signature():
    parameters = list(inspect.signature(percentile).parameters.values())
    assert [parameter.name for parameter in parameters] == ["values", "p"]
    assert all(
        parameter.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD
        for parameter in parameters
    )
    assert all(
        parameter.default is inspect.Parameter.empty
        for parameter in parameters
    )
    assert all(
        parameter.annotation is inspect.Parameter.empty
        for parameter in parameters
    )


