import inspect

from settings import merge


def test_merge_returns_new_dict():
    base = {'a': 1}
    override = {'b': 2}
    result = merge(base, override)
    assert isinstance(result, dict)
    assert result is not base
    assert result is not override


def test_merge_returns_base_overlaid_with_override():
    base = {'a': 1, 'b': 0}
    override = {'b': 2, 'c': 3}
    result = merge(base, override)
    assert result == {'a': 1, 'b': 2, 'c': 3}
    assert result['a'] == 1
    assert result['b'] == 2
    assert result['c'] == 3


def test_merge_does_not_modify_base():
    base = {'a': 1, 'b': 0}
    base_before = base.copy()
    override = {'b': 2, 'c': 3}
    merge(base, override)
    assert base == base_before


def test_merge_does_not_modify_override():
    base = {'a': 1}
    override = {'b': 2, 'c': 3}
    override_before = override.copy()
    merge(base, override)
    assert override == override_before


def test_merge_signature_unchanged():
    sig = inspect.signature(merge)
    assert tuple(sig.parameters) == ('base', 'override')
    for param in sig.parameters.values():
        assert param.default is inspect.Parameter.empty
        assert param.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD

