import grouping


def test_do_group_by_returns_dict_mapping_each_key_to_list_of_items():
    items = ["apple", "avocado", "banana", "cherry"]
    result = grouping.group_by(items, len)

    assert isinstance(result, dict)
    assert set(result) == {5, 6}
    assert all(isinstance(group, list) for group in result.values())
    assert result[5] == ["apple"]
    assert result[6] == ["avocado", "banana", "cherry"]


def test_do_each_group_list_contains_exactly_items_with_matching_key():
    items = [1, 2, 3, 4, 5, 6]
    key = lambda x: x % 3
    result = grouping.group_by(items, key)

    assert result == {0: [3, 6], 1: [1, 4], 2: [2, 5]}
    for group_key, group in result.items():
        assert [item for item in items if key(item) == group_key] == group
        assert all(key(item) == group_key for item in group)


def test_do_each_group_list_preserves_input_order():
    items = ["a", "bb", "ccc", "dd", "e", "ffff"]
    result = grouping.group_by(items, len)

    assert result[1] == ["a", "e"]
    assert result[2] == ["bb", "dd"]
    assert result[3] == ["ccc"]
    assert result[4] == ["ffff"]


def test_do_each_group_list_is_independent_list_object():
    items = ["x", "yy", "zzz", "ww"]
    result = grouping.group_by(items, len)

    groups = list(result.values())
    for i in range(len(groups)):
        for j in range(i + 1, len(groups)):
            assert groups[i] is not groups[j]

    result[2].append("aa")
    assert result[3] == ["zzz"]


def test_do_group_by_parity_returns_expected_groups():
    result = grouping.group_by([1, 2, 3, 4], lambda x: x % 2)

    assert result == {1: [1, 3], 0: [2, 4]}


def test_do_single_group_input_returns_all_items_in_input_order():
    items = [10, 30, 20]
    result = grouping.group_by(items, lambda x: "all")

    assert result == {"all": [10, 30, 20]}


def test_avoid_group_by_signature_is_unchanged():
    sig = inspect.signature(grouping.group_by)

    assert str(sig) == "(items, key)"
    assert list(sig.parameters) == ["items", "key"]
    for name in ("items", "key"):
        assert sig.parameters[name].default is inspect.Parameter.empty
        assert sig.parameters[name].kind == inspect.Parameter.POSITIONAL_OR_KEYWORD

