from pairs import pairs


def test_return_tuple_for_every_pair_distinct_positions():
    assert pairs([10, 20, 30]) == [(10, 20), (10, 30), (20, 30)]


def test_put_item_from_smaller_position_first():
    result = pairs([0, 1, 2])
    for a, b in result:
