def test_do_not_return_tuples_with_first_index_not_less_than_second():
    result = pairs([0, 1, 2])
    assert not any(a >= b for a, b in result)


def test_do_not_return_same_pair_of_positions_more_than_once():
    result = pairs([0, 1, 2])
    assert len({frozenset(t) for t in result}) == len(result)


def test_treat_two_positions_as_distinct_even_if_values_equal():
    result = pairs(['a', 'a', 'a'])
    assert len(result) == 3
    assert all(t == ('a', 'a') for t in result)


def test_return_aa_for_pairs_aa():
    assert pairs(['a', 'a']) == [('a', 'a')]


def test_do_not_change_signature():
