    assert list(sig.parameters) == ['items']

import inspect

from editdist import distance


def test_fix_bug_returns_levenshtein_distance():
    cases = [
        ("a", "", 1),
        ("", "a", 1),
        ("a", "b", 1),
        ("abc", "abd", 1),
        ("ab", "a", 1),
        ("a", "ab", 1),
        ("kitten", "sitting", 3),
    ]
    for a, b, expected in cases:
        assert distance(a, b) == expected


def test_distance_cat_cut_returns_1():
    assert distance("cat", "cut") == 1


def test_distance_kitten_sitting_returns_3():
    assert distance("kitten", "sitting") == 3


def test_distance_returns_correct_for_pure_insertions():
    insertion_pairs = [
        ("cat", "cats"),
        ("cat", "scat"),
        ("cat", "cast"),
        ("ab", "acb"),
        ("", "abc"),
    ]
    for a, b in insertion_pairs:
        assert distance(a, b) == len(b) - len(a)


def test_distance_returns_0_for_identical_strings():
    for s in ("", "cat", "kitten"):
        assert distance(s, s) == 0


def test_signature_of_distance_unchanged():
    sig = inspect.signature(distance)
    assert list(sig.parameters) == ["a", "b"]
    for parameter in sig.parameters.values():
        assert parameter.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD
        assert parameter.default is inspect.Parameter.empty


def test_distance_still_correct_for_pure_insertions_and_identical_strings():
    insertion_pairs = [
        ("cat", "cats"),
        ("cat", "scat"),
        ("cat", "cast"),
        ("ab", "acb"),
        ("", "abc"),
    ]
    for a, b in insertion_pairs:
        assert distance(a, b) == len(b) - len(a)

    for s in ("", "cat", "kitten"):
        assert distance(s, s) == 0

