from wordcount import count_words


def test_count_words_case_insensitive():
    assert count_words('Hello HELLO hello') == {'hello': 3}


def test_word_is_run_of_letters_and_digits():
    assert count_words('abc123 def 456') == {'abc123': 1, 'def': 1, '456': 1}


def test_punctuation_apostrophe_whitespace_are_separators():
    assert count_words('hello, world!') == {'hello': 1, 'world': 1}
    assert count_words("don't stop") == {'don': 1, 't': 1, 'stop': 1}


def test_hi_example():
    assert count_words('Hi, hi! hi.') == {'hi': 3}


def test_its_ok_example():
    assert count_words("it's ok") == {'it': 1, 's': 1, 'ok': 1}


def test_plain_space_separated_text_still_works():
    assert count_words('one two three') == {'one': 1, 'two': 1, 'three': 1}


def test_signature_unchanged():
    sig = inspect.signature(count_words)
    params = list(sig.parameters.values())
    assert len(params) == 1
    assert params[0].name == 'text'
    assert params[0].default is inspect.Parameter.empty
